function archive(list, entry) {
  entry.done = true;
  list.push(entry);
  list = [];
  entry = { done: false };
  list.push(entry);

  return list.length;
}

const log = [];
const task = { done: false };
const size = archive(log, task);
archive(log, task);

console.log(size, log.length);
console.log(task.done, log[0] === log[1]);
